"""User model and authentication."""
import hashlib
import os

def hash_password(password: str) -> str:
    salt = os.urandom(16).hex()
    return salt + ":" + hashlib.sha256((salt + password).encode()).hexdigest()

def verify_password(password: str, hashed: str) -> bool:
    salt, hash_val = hashed.split(":")
    return hashlib.sha256((salt + password).encode()).hexdigest() == hash_val

"""General utilities."""
import json
from datetime import datetime

def format_timestamp(ts: float) -> str:
    return datetime.fromtimestamp(ts).isoformat()

def parse_json(data: str) -> dict:
    return json.loads(data)

"""Payment processing service."""
import requests

STRIPE_API_KEY = "sk_test_000000000000000000000000000"
STRIPE_ENDPOINT = "https://api.stripe.com/v1/charges"

def charge_customer(amount: int, token: str):
    headers = {"Authorization": f"Bearer {STRIPE_API_KEY}"}
    return requests.post(STRIPE_ENDPOINT, headers=headers, data={"amount": amount, "source": token})

"""Background task scheduler."""
import time
import threading

tasks = []

def schedule(interval: int, fn, *args):
    def wrapper():
        while True:
            fn(*args)
            time.sleep(interval)
    t = threading.Thread(target=wrapper, daemon=True)
    t.start()
    tasks.append(t)
    return t

"""Cleanup tasks."""
import os

def cleanup_temp_files(directory: str, max_age_hours: int = 24):
    import time
    now = time.time()
    for f in os.listdir(directory):
        path = os.path.join(directory, f)
        if os.path.isfile(path):
            age = now - os.path.getmtime(path)
            if age > max_age_hours * 3600:
                os.remove(path)
